"""Pure-Lua scripts for DaVinci Resolve (compatible with both Resolve Free and Studio)."""

from __future__ import annotations

from obol.plugins.reaper_scripts import _lua_long_str

OBOL_INTEGRATION_VERSION = "1.1"


def render_resolve_config_lua(
    python_exe: str,
    pythonw_exe: str,
    pythonpath: str,
    obol_home: str,
    bridge_dir: str,
) -> str:
    """Generates machine-local `Utility/Obol/obol_resolve_config.lua`."""
    return "\n".join([
        "-- Auto-generated by Obol DaVinci Resolve Installer. Do not edit manually.",
        "return {",
        f"  INTEGRATION_VERSION = {_lua_long_str(OBOL_INTEGRATION_VERSION)},",
        f"  PYTHON_EXE = {_lua_long_str(python_exe)},",
        f"  PYTHONW_EXE = {_lua_long_str(pythonw_exe)},",
        f"  PYTHONPATH = {_lua_long_str(pythonpath)},",
        f"  OBOL_HOME = {_lua_long_str(obol_home)},",
        f"  BRIDGE_DIR = {_lua_long_str(bridge_dir)},",
        "}",
        "",
    ])


def render_resolve_lib_lua() -> str:
    """Generates shared pure-Lua JSON, runner, and Resolve API helpers (`Utility/Obol/obol_resolve_lib.lua`)."""
    return r'''-- Obol Shared Lua Library for DaVinci Resolve (Free & Studio compatible)
local M = {}

local function get_script_dir()
  local info = debug.getinfo(1, "S")
  local src = info and info.source or ""
  if src:sub(1, 1) == "@" then src = src:sub(2) end
  return src:match("^(.*[/\\])") or ""
end

M.LIB_DIR = get_script_dir()
M.CONFIG = dofile(M.LIB_DIR .. "obol_resolve_config.lua")
M.IS_WIN = (package.config:sub(1, 1) == "\\")

function M.norm_sep(p)
  if not p then return "" end
  return tostring(p):gsub("\\", "/")
end

function M.norm_key(p)
  local s = M.norm_sep(p)
  if M.IS_WIN then s = s:lower() end
  return s
end

function M.file_exists(path)
  local f = io.open(path, "rb")
  if f then f:close(); return true end
  return false
end

function M.read_file(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local data = f:read("*a")
  f:close()
  return data
end

function M.write_atomic(path, content)
  local tmp = path .. ".tmp"
  local f, err = io.open(tmp, "wb")
  if not f then return false, err end
  f:write(content)
  f:close()
  os.remove(path)
  local ok, rerr = os.rename(tmp, path)
  if not ok then
    os.remove(tmp)
    return false, rerr
  end
  return true
end

function M.ensure_dir(path)
  if not path or path == "" then return end
  if bmd and bmd.createdir then
    bmd.createdir(path)
  end
end

function M.wait_sec(sec)
  if bmd and bmd.wait then
    bmd.wait(sec)
  else
    local t0 = os.clock()
    while os.clock() - t0 < sec do end
  end
end

function M.list_dir_files(dir_path)
  local found = {}
  if not dir_path or dir_path == "" then return found end
  if bmd and bmd.readdir then
    local ok, entries = pcall(bmd.readdir, M.norm_sep(dir_path) .. "/*")
    if ok and type(entries) == "table" then
      for _, entry in ipairs(entries) do
        if type(entry) == "table" and entry.Name and not entry.IsDir then
          local name = tostring(entry.Name)
          if name ~= "." and name ~= ".." and not name:match("^%.") then
            found[name] = M.norm_sep(dir_path .. "/" .. name)
          end
        end
      end
      return found
    end
  end
  return found
end

function M.empty_array()
  return setmetatable({}, { __obol_array = true })
end

-- Minimal pure-Lua JSON encoder/decoder
local json = {}
local escape_map = {
  ["\\"] = "\\\\",
  ['"'] = '\\"',
  ["\b"] = "\\b",
  ["\f"] = "\\f",
  ["\n"] = "\\n",
  ["\r"] = "\\r",
  ["\t"] = "\\t",
}

local function encode_str(s)
  return '"' .. s:gsub('[\\"\b\f\n\r\t%z\1-\31]', function(c)
    if escape_map[c] then return escape_map[c] end
    return string.format("\\u%04x", string.byte(c))
  end) .. '"'
end

local function is_array(t)
  local mt = getmetatable(t)
  if mt and mt.__obol_array then return true end
  local max_i = 0
  local count = 0
  for k, _ in pairs(t) do
    if type(k) ~= "number" or k < 1 or math.floor(k) ~= k then return false end
    if k > max_i then max_i = k end
    count = count + 1
  end
  return count > 0 and max_i == count
end

function json.encode(val)
  local tv = type(val)
  if val == nil then return "null" end
  if tv == "boolean" then return val and "true" or "false" end
  if tv == "number" then
    if val ~= val or val == math.huge or val == -math.huge then return "null" end
    return tostring(val)
  end
  if tv == "string" then return encode_str(val) end
  if tv == "table" then
    local parts = {}
    if is_array(val) then
      for i = 1, #val do
        parts[#parts + 1] = json.encode(val[i])
      end
      return "[" .. table.concat(parts, ",") .. "]"
    else
      for k, v in pairs(val) do
        if v ~= nil then
          parts[#parts + 1] = encode_str(tostring(k)) .. ":" .. json.encode(v)
        end
      end
      return "{" .. table.concat(parts, ",") .. "}"
    end
  end
  return "null"
end

function json.decode(str)
  if type(str) ~= "string" then return nil, "not a string" end
  local pos = 1
  local len = #str

  local function skip_ws()
    while pos <= len do
      local c = str:sub(pos, pos)
      if c == " " or c == "\t" or c == "\r" or c == "\n" then
        pos = pos + 1
      else
        break
      end
    end
  end

  local parse_value

  local function parse_string()
    pos = pos + 1
    local out = {}
    while pos <= len do
      local c = str:sub(pos, pos)
      if c == '"' then
        pos = pos + 1
        return table.concat(out)
      elseif c == "\\" then
        pos = pos + 1
        local esc = str:sub(pos, pos)
        if esc == '"' or esc == "\\" or esc == "/" then out[#out + 1] = esc
        elseif esc == "b" then out[#out + 1] = "\b"
        elseif esc == "f" then out[#out + 1] = "\f"
        elseif esc == "n" then out[#out + 1] = "\n"
        elseif esc == "r" then out[#out + 1] = "\r"
        elseif esc == "t" then out[#out + 1] = "\t"
        elseif esc == "u" then
          local hex = str:sub(pos + 1, pos + 4)
          local code = tonumber(hex, 16)
          if code then
            if code < 128 then
              out[#out + 1] = string.char(code)
            elseif code < 2048 then
              out[#out + 1] = string.char(192 + math.floor(code / 64), 128 + (code % 64))
            else
              out[#out + 1] = string.char(
                224 + math.floor(code / 4096),
                128 + (math.floor(code / 64) % 64),
                128 + (code % 64)
              )
            end
            pos = pos + 4
          end
        end
        pos = pos + 1
      else
        out[#out + 1] = c
        pos = pos + 1
      end
    end
    error("Unterminated JSON string")
  end

  local function parse_array()
    pos = pos + 1
    local arr = M.empty_array()
    skip_ws()
    if str:sub(pos, pos) == "]" then pos = pos + 1; return arr end
    while pos <= len do
      arr[#arr + 1] = parse_value()
      skip_ws()
      local ch = str:sub(pos, pos)
      if ch == "]" then pos = pos + 1; return arr
      elseif ch == "," then pos = pos + 1
      else error("Expected ',' or ']' at pos " .. pos) end
    end
    error("Unterminated JSON array")
  end

  local function parse_object()
    pos = pos + 1
    local obj = {}
    skip_ws()
    if str:sub(pos, pos) == "}" then pos = pos + 1; return obj end
    while pos <= len do
      skip_ws()
      local key = parse_string()
      skip_ws()
      if str:sub(pos, pos) ~= ":" then error("Expected ':' at pos " .. pos) end
      pos = pos + 1
      obj[key] = parse_value()
      skip_ws()
      local ch = str:sub(pos, pos)
      if ch == "}" then pos = pos + 1; return obj
      elseif ch == "," then pos = pos + 1
      else error("Expected ',' or '}' at pos " .. pos) end
    end
    error("Unterminated JSON object")
  end

  parse_value = function()
    skip_ws()
    local c = str:sub(pos, pos)
    if c == '"' then return parse_string() end
    if c == "{" then return parse_object() end
    if c == "[" then return parse_array() end
    if str:sub(pos, pos + 3) == "true" then pos = pos + 4; return true end
    if str:sub(pos, pos + 4) == "false" then pos = pos + 5; return false end
    if str:sub(pos, pos + 3) == "null" then pos = pos + 4; return nil end
    local num_str = str:match("^%-?%d+%.?%d*[eE]?[%+%-]?%d*", pos)
    if num_str and #num_str > 0 then pos = pos + #num_str; return tonumber(num_str) end
    error("Unexpected token at pos " .. pos)
  end

  local ok, res = pcall(parse_value)
  if not ok then return nil, res end
  return res
end

M.json = json

function M.get_resolve()
  if resolve then return resolve end
  if app and app.GetResolve then
    local ok, r = pcall(function() return app:GetResolve() end)
    if ok and r then return r end
  end
  if bmd and bmd.scriptapp then
    local ok, r = pcall(bmd.scriptapp, "Resolve")
    if ok and r then return r end
  end
  return nil
end

local function py_quote(s)
  return '"' .. tostring(s):gsub("\\", "\\\\"):gsub('"', '\\"') .. '"'
end

function M.run_obol_cli(cli_args, capture_output, background)
  local tmp_dir = M.CONFIG.BRIDGE_DIR .. "/tmp"
  M.ensure_dir(tmp_dir)
  local uid = tostring(os.time()) .. "_" .. tostring(math.random(10000, 99999))
  local runner_path = tmp_dir .. "/obol_run_" .. uid .. ".py"
  local out_path = tmp_dir .. "/obol_out_" .. uid .. ".txt"

  local argv_parts = { py_quote("obol") }
  for _, a in ipairs(cli_args) do
    argv_parts[#argv_parts + 1] = py_quote(a)
  end

  local lines = {
    "import os, sys, contextlib",
  }
  if M.CONFIG.PYTHONPATH and M.CONFIG.PYTHONPATH ~= "" then
    lines[#lines + 1] = "sys.path.insert(0, " .. py_quote(M.CONFIG.PYTHONPATH) .. ")"
  end
  if M.CONFIG.OBOL_HOME and M.CONFIG.OBOL_HOME ~= "" then
    lines[#lines + 1] = "os.environ['OBOL_HOME'] = " .. py_quote(M.CONFIG.OBOL_HOME)
  end
  lines[#lines + 1] = "sys.argv = [" .. table.concat(argv_parts, ", ") .. "]"
  lines[#lines + 1] = "from obol.cli.main import run_cli"
  if capture_output then
    lines[#lines + 1] = "with open(" .. py_quote(out_path) .. ", 'w', encoding='utf-8') as _f:"
    lines[#lines + 1] = "    with contextlib.redirect_stdout(_f):"
    lines[#lines + 1] = "        _rc = run_cli(sys.argv[1:])"
  else
    lines[#lines + 1] = "_rc = run_cli(sys.argv[1:])"
  end
  lines[#lines + 1] = "sys.exit(_rc)"

  M.write_atomic(runner_path, table.concat(lines, "\n") .. "\n")

  local exe = M.CONFIG.PYTHONW_EXE or M.CONFIG.PYTHON_EXE
  if background then
    if M.IS_WIN then
      os.execute('start "" "' .. exe .. '" "' .. runner_path .. '"')
    else
      os.execute('"' .. exe .. '" "' .. runner_path .. '" >/dev/null 2>&1 &')
    end
    return true, ""
  end

  local cmd
  if M.IS_WIN then
    cmd = '""' .. exe .. '" "' .. runner_path .. '""'
  else
    cmd = '"' .. exe .. '" "' .. runner_path .. '"'
  end
  local rc = os.execute(cmd)
  os.remove(runner_path)

  local out = ""
  if capture_output then
    out = M.read_file(out_path) or ""
    os.remove(out_path)
  end
  local ok = (rc == true or rc == 0)
  return ok, out
end

local function extract_preset_names(raw)
  local res = M.empty_array()
  if type(raw) ~= "table" then return res end
  local seen = {}
  for _, v in pairs(raw) do
    local name = nil
    if type(v) == "table" and v.Name then
      name = tostring(v.Name)
    elseif type(v) == "string" and v ~= "" then
      name = v
    end
    if name and not seen[name] then
      seen[name] = true
      res[#res + 1] = name
    end
  end
  return res
end

function M.walk_media_pool(folder, prefix, out_list)
  if not folder then return end
  local fname = folder:GetName() or ""
  local curr = (prefix and prefix ~= "") and (prefix .. "/" .. fname) or fname
  local clips = folder:GetClipList()
  if type(clips) == "table" then
    for _, clip in pairs(clips) do
      local fpath = ""
      local okp, pval = pcall(function() return clip:GetClipProperty("File Path") end)
      if okp and pval then fpath = tostring(pval) end
      local mid = ""
      if clip.GetMediaId then
        local okm, mval = pcall(function() return clip:GetMediaId() end)
        if okm and mval then mid = tostring(mval) end
      end
      out_list[#out_list + 1] = {
        name = clip:GetName() or "",
        file_path = M.norm_sep(fpath),
        bin_path = curr,
        media_id = mid,
      }
    end
  end
  local subs = folder:GetSubFolderList()
  if type(subs) == "table" then
    for _, sub in pairs(subs) do
      M.walk_media_pool(sub, curr, out_list)
    end
  end
end

function M.collect_context(res, include_clips)
  local pm = res and res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  local tl = proj and proj:GetCurrentTimeline()
  local mp = proj and proj:GetMediaPool()
  local curr_bin = mp and mp:GetCurrentFolder()

  local render_presets = M.empty_array()
  local qe_presets = M.empty_array()
  if proj then
    local ok1, rp = pcall(function() return proj:GetRenderPresetList() end)
    if ok1 then render_presets = extract_preset_names(rp) end
    if proj.GetQuickExportRenderPresets then
      local ok2, qep = pcall(function() return proj:GetQuickExportRenderPresets() end)
      if ok2 then qe_presets = extract_preset_names(qep) end
    end
  end

  local clips = M.empty_array()
  if include_clips and mp then
    local root = mp:GetRootFolder()
    M.walk_media_pool(root, "", clips)
  end

  return {
    product_name = (res and res:GetProductName()) or "DaVinci Resolve",
    version = (res and res:GetVersionString()) or "",
    project_name = (proj and proj:GetName()) or "",
    timeline_name = (tl and tl:GetName()) or "",
    current_page = (res and res:GetCurrentPage()) or "",
    current_bin = (curr_bin and curr_bin:GetName()) or "",
    render_presets = render_presets,
    quick_export_presets = qe_presets,
    media_pool_clips = clips,
  }
end

local function ensure_bin(mp, bin_path)
  local clean = M.norm_sep(bin_path):gsub("^/+", ""):gsub("/+$", "")
  if clean == "" then return mp:GetCurrentFolder() end
  local curr = mp:GetRootFolder()
  if clean:lower() == "root" or clean:lower() == "master" then
    mp:SetCurrentFolder(curr)
    return curr
  end
  for seg in clean:gmatch("[^/]+") do
    local found = nil
    local subs = curr:GetSubFolderList() or {}
    for _, f in pairs(subs) do
      if f:GetName() == seg then found = f; break end
    end
    if not found then
      found = mp:AddSubFolder(curr, seg)
    end
    if not found then error("Failed to create/open Media Pool bin: " .. seg) end
    curr = found
  end
  mp:SetCurrentFolder(curr)
  return curr
end

function M.exec_import_media(res, params)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local mp = proj:GetMediaPool()

  local paths = params.file_paths or {}
  if #paths == 0 then error("No file paths provided to import_media.") end

  if params.bin_path and params.bin_path ~= "" then
    ensure_bin(mp, params.bin_path)
  end

  local clips = mp:ImportMedia(paths) or {}
  if type(params.asset_meta) == "table" and next(params.asset_meta) ~= nil then
    local meta = {}
    for k, v in pairs(params.asset_meta) do
      meta["obol_" .. tostring(k)] = tostring(v)
    end
    for _, clip in pairs(clips) do
      pcall(function() clip:SetThirdPartyMetadata(meta) end)
    end
  end

  if params.append_to_timeline and next(clips) ~= nil then
    mp:AppendToTimeline(clips)
  end

  local cnt = 0
  for _ in pairs(clips) do cnt = cnt + 1 end
  local curr_folder = mp:GetCurrentFolder()
  return { imported = cnt, bin = (curr_folder and curr_folder:GetName()) or "" }
end

function M.exec_query_media_pool(res)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local mp = proj:GetMediaPool()
  local items = M.empty_array()
  M.walk_media_pool(mp:GetRootFolder(), "", items)
  return { items = items }
end

local function walk_replace_clips(folder, rep_map, state)
  local clips = folder:GetClipList() or {}
  for _, clip in pairs(clips) do
    local okp, fpath = pcall(function() return clip:GetClipProperty("File Path") end)
    if okp and fpath then
      local target = rep_map[M.norm_key(fpath)]
      if target and target ~= "" then
        local ok_rep = false
        if clip.ReplaceClipPreserveSubClip then
          local ok1, r1 = pcall(function() return clip:ReplaceClipPreserveSubClip(target) end)
          ok_rep = ok1 and r1
        end
        if not ok_rep and clip.ReplaceClip then
          local ok2, r2 = pcall(function() return clip:ReplaceClip(target) end)
          ok_rep = ok2 and r2
        end
        if ok_rep then state.replaced = state.replaced + 1 end
      end
    end
  end
  local subs = folder:GetSubFolderList() or {}
  for _, sub in pairs(subs) do
    walk_replace_clips(sub, rep_map, state)
  end
end

function M.exec_replace_clips(res, params)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local mp = proj:GetMediaPool()
  local rep_map = {}
  for k, v in pairs(params.replacements or {}) do
    rep_map[M.norm_key(k)] = v
  end
  local state = { replaced = 0 }
  walk_replace_clips(mp:GetRootFolder(), rep_map, state)
  return { replaced = state.replaced }
end

function M.exec_render_deliver_job(res, params)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local out_dir = params.output_dir
  if not out_dir or out_dir == "" then error("Missing output_dir") end
  M.ensure_dir(out_dir)

  local before = M.list_dir_files(out_dir)
  if params.preset_name and params.preset_name ~= "" then
    proj:LoadRenderPreset(params.preset_name)
  end
  local settings = {
    TargetDir = out_dir,
    SelectAllFrames = (params.select_all_frames ~= false),
  }
  if params.custom_name and params.custom_name ~= "" then
    settings.CustomName = params.custom_name
  end
  proj:SetRenderSettings(settings)
  local job_id = proj:AddRenderJob()
  if not job_id or job_id == "" then
    error("Failed to add render job in DaVinci Resolve.")
  end
  proj:StartRendering(job_id)
  while proj:IsRenderingInProgress() do
    M.wait_sec(0.25)
  end
  local status = proj:GetRenderJobStatus(job_id) or {}
  local after = M.list_dir_files(out_dir)
  local rendered = M.empty_array()
  for fname, fullp in pairs(after) do
    if not before[fname] then rendered[#rendered + 1] = fullp end
  end
  table.sort(rendered)
  return { job_id = job_id, status = status, rendered_files = rendered }
end

function M.exec_render_quick_export(res, params)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local out_dir = params.output_dir
  if not out_dir or out_dir == "" then error("Missing output_dir") end
  M.ensure_dir(out_dir)
  local before = M.list_dir_files(out_dir)
  local q_params = { TargetDir = out_dir }
  if params.custom_name and params.custom_name ~= "" then
    q_params.CustomName = params.custom_name
  end
  local status = proj:RenderWithQuickExport(params.preset_name or "", q_params)
  local after = M.list_dir_files(out_dir)
  local rendered = M.empty_array()
  for fname, fullp in pairs(after) do
    if not before[fname] then rendered[#rendered + 1] = fullp end
  end
  table.sort(rendered)
  return { status = status, rendered_files = rendered }
end

function M.exec_stage_deliver_page(res, params)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local out_dir = params.output_dir
  if not out_dir or out_dir == "" then error("Missing output_dir") end
  M.ensure_dir(out_dir)
  res:OpenPage("deliver")
  if params.preset_name and params.preset_name ~= "" then
    proj:LoadRenderPreset(params.preset_name)
  end
  local settings = { TargetDir = out_dir }
  if params.custom_name and params.custom_name ~= "" then
    settings.CustomName = params.custom_name
  end
  proj:SetRenderSettings(settings)
  local job_id = ""
  if params.add_job then
    job_id = proj:AddRenderJob() or ""
  end
  return { staged_dir = M.norm_sep(out_dir), job_id = job_id }
end

function M.exec_export_current_still(res, params)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local out_file = params.output_file
  if not out_file or out_file == "" then error("Missing output_file") end
  local parent = out_file:match("^(.*)[/\\][^/\\]+$")
  if parent then M.ensure_dir(parent) end
  local ok = proj:ExportCurrentFrameAsStill(out_file)
  if not ok then error("Resolve failed to export current frame still.") end
  return { output_file = M.norm_sep(out_file) }
end

function M.exec_export_project_drp(res, params)
  local pm = res:GetProjectManager()
  local proj = pm and pm:GetCurrentProject()
  if not proj then error("No DaVinci Resolve project is currently open.") end
  local out_file = params.output_file
  if not out_file or out_file == "" then error("Missing output_file") end
  local parent = out_file:match("^(.*)[/\\][^/\\]+$")
  if parent then M.ensure_dir(parent) end
  local ok = pm:ExportProject(proj:GetName(), out_file, params.with_stills_and_luts ~= false)
  if not ok then error("Resolve failed to export .drp snapshot.") end
  return { output_file = M.norm_sep(out_file) }
end

function M.dispatch(res, action, params)
  if action == "import_media" then return M.exec_import_media(res, params)
  elseif action == "query_media_pool" then return M.exec_query_media_pool(res)
  elseif action == "replace_media_pool_clips" then return M.exec_replace_clips(res, params)
  elseif action == "render_deliver_job" then return M.exec_render_deliver_job(res, params)
  elseif action == "render_quick_export" then return M.exec_render_quick_export(res, params)
  elseif action == "stage_deliver_page" then return M.exec_stage_deliver_page(res, params)
  elseif action == "export_current_still" then return M.exec_export_current_still(res, params)
  elseif action == "export_project_drp" then return M.exec_export_project_drp(res, params)
  else error("Unknown Obol Resolve action: " .. tostring(action))
  end
end

return M
'''


def _load_lib_preamble(lib_rel_path: str) -> str:
    return (
        'local info = debug.getinfo(1, "S")\n'
        'local src = info and info.source or ""\n'
        'if src:sub(1, 1) == "@" then src = src:sub(2) end\n'
        'local script_dir = src:match("^(.*[/\\\\])") or ""\n'
        f'local obol = dofile(script_dir .. "{lib_rel_path}")\n'
    )


def render_resolve_import_action_lua() -> str:
    return _load_lib_preamble("Obol/obol_resolve_lib.lua") + r'''
local res = obol.get_resolve()
if not res then return end

local tmp_dir = obol.CONFIG.BRIDGE_DIR .. "/tmp"
obol.ensure_dir(tmp_dir)
local uid = tostring(os.time()) .. "_" .. tostring(math.random(1000, 9999))
local ctx_file = tmp_dir .. "/ctx_" .. uid .. ".json"
local res_file = tmp_dir .. "/res_" .. uid .. ".json"

local ctx = obol.collect_context(res, true)
obol.write_atomic(ctx_file, obol.json.encode(ctx))

obol.run_obol_cli({
  "resolve", "ui", "--mode", "import",
  "--context-file", ctx_file,
  "--result-file", res_file,
}, false, false)

os.remove(ctx_file)
local raw = obol.read_file(res_file)
os.remove(res_file)
if not raw or raw == "" then return end

local plan = obol.json.decode(raw)
if type(plan) == "table" and plan.action then
  local ok, err = pcall(obol.dispatch, res, plan.action, plan.params or {})
  if not ok then
    print("[Obol] Import error: " .. tostring(err))
  end
end
'''


def render_resolve_publish_action_lua(lib_rel_path: str = "Obol/obol_resolve_lib.lua") -> str:
    return _load_lib_preamble(lib_rel_path) + r'''
local res = obol.get_resolve()
if not res then return end

local tmp_dir = obol.CONFIG.BRIDGE_DIR .. "/tmp"
obol.ensure_dir(tmp_dir)
local uid = tostring(os.time()) .. "_" .. tostring(math.random(1000, 9999))
local ctx_file = tmp_dir .. "/ctx_" .. uid .. ".json"
local res_file = tmp_dir .. "/res_" .. uid .. ".json"

local ctx = obol.collect_context(res, false)
obol.write_atomic(ctx_file, obol.json.encode(ctx))

obol.run_obol_cli({
  "resolve", "ui", "--mode", "publish",
  "--context-file", ctx_file,
  "--result-file", res_file,
}, false, false)

os.remove(ctx_file)
local raw = obol.read_file(res_file)
os.remove(res_file)
if not raw or raw == "" then return end

local plan = obol.json.decode(raw)
if type(plan) ~= "table" then return end

if plan.drp_snapshot and type(plan.drp_snapshot) == "table" then
  local snap_path = tmp_dir .. "/snapshot_" .. uid .. ".drp"
  local ok_drp = pcall(obol.exec_export_project_drp, res, {
    output_file = snap_path,
    with_stills_and_luts = true,
  })
  if ok_drp and obol.file_exists(snap_path) then
    obol.run_obol_cli({
      "work", "ingest", snap_path,
      "-p", plan.drp_snapshot.project_name,
      "-t", plan.drp_snapshot.component_path,
      "-m", plan.drp_snapshot.comment or "Resolve .drp working snapshot",
    }, false, false)
    os.remove(snap_path)
  end
end

if plan.action and plan.action ~= "noop" then
  local ok, result = pcall(obol.dispatch, res, plan.action, plan.params or {})
  if not ok then
    print("[Obol] Publish error: " .. tostring(result))
    return
  end
end

if plan.sync_args and type(plan.sync_args) == "table" then
  local sa = plan.sync_args
  local cli_cmd = {
    "resolve", "sync-publish",
    "-p", sa.project_name,
    "-t", sa.component_path,
    "--name", sa.deliverable_name,
    "--version", tostring(sa.version),
    "-m", sa.comment or "",
    "--json",
  }
  if sa.source_working_version and tonumber(sa.source_working_version) then
    cli_cmd[#cli_cmd + 1] = "--from-working"
    cli_cmd[#cli_cmd + 1] = tostring(sa.source_working_version)
  end
  if type(sa.tags) == "table" then
    for _, tg in ipairs(sa.tags) do
      cli_cmd[#cli_cmd + 1] = "--tag"
      cli_cmd[#cli_cmd + 1] = tostring(tg)
    end
  end
  obol.run_obol_cli(cli_cmd, true, false)
end
'''


def render_resolve_live_bridge_lua() -> str:
    return _load_lib_preamble("Obol/obol_resolve_lib.lua") + r'''
local res = obol.get_resolve()
if not res then return end

local bridge_dir = obol.CONFIG.BRIDGE_DIR
local inbox_dir = bridge_dir .. "/inbox"
local outbox_dir = bridge_dir .. "/outbox"
local state_path = bridge_dir .. "/state.json"
local stop_flag = bridge_dir .. "/stop.flag"

obol.ensure_dir(bridge_dir)
obol.ensure_dir(inbox_dir)
obol.ensure_dir(outbox_dir)
os.remove(stop_flag)

local function write_state(connected)
  local ctx = obol.collect_context(res, false)
  ctx.connected = connected
  ctx.heartbeat = os.time()
  obol.write_atomic(state_path, obol.json.encode(ctx))
end

write_state(true)
local last_hb = os.time()

while not obol.file_exists(stop_flag) do
  local files = {}
  local listed = obol.list_dir_files(inbox_dir)
  for fname, _ in pairs(listed) do
    if fname:match("%.json$") then files[#files + 1] = fname end
  end
  table.sort(files)

  for _, fname in ipairs(files) do
    local full_in = inbox_dir .. "/" .. fname
    local raw = obol.read_file(full_in)
    os.remove(full_in)
    if raw and raw ~= "" then
      local req = obol.json.decode(raw)
      if type(req) == "table" and req.id then
        local ok, result = pcall(obol.dispatch, res, req.action, req.params or {})
        local resp
        if ok then
          resp = { id = req.id, ok = true, result = result or {} }
        else
          resp = { id = req.id, ok = false, error = tostring(result) }
        end
        obol.write_atomic(outbox_dir .. "/" .. tostring(req.id) .. ".json", obol.json.encode(resp))
      end
    end
  end

  local now = os.time()
  if now - last_hb >= 2 then
    last_hb = now
    pcall(write_state, true)
  end
  obol.wait_sec(0.2)
end

os.remove(stop_flag)
pcall(write_state, false)
'''


